PUNCTUATE=PUNCTUO+[['拉丁分词 punctuatus；英语较早名词 punctuation','早期动词有拉丁借入；现代常用义也有名词反构分析'],['英语：punctuate','加标点；不时插入、打断或强调']]
PUNCTURE=P+[['后期拉丁语：punctura','刺孔；刺破'],['英语：puncture','小孔；刺破、扎破']]
PUNGENT=P+[['拉丁语：pungens，词干 pungent-','正在刺的；尖锐刺激的'],['英语：pungent','刺鼻、辛辣；尖锐有力的']]
