EXP=P+[['拉丁语：ex- + pungere → expungere','向外 + 刺 → 用点标出应删的文字']]
EXPUNGE=EXP+[['英语：expunge','删去、抹去；从记录中清除']]
COMP=P+[['拉丁语：com- + pungere → compungere','加强语气 + 刺 → 刺痛'],['后期拉丁语 compunctio → 古法语 compunction','心里被刺痛 → 良心不安'],['中古英语 compunccion → 英语 compunction','内疚；因不安而不愿做某事']]
PUNCTILIO=PT+[['意大利语 punto → puntiglio；或西班牙语 punto → puntillo','点 → 小细节；礼节上的讲究'],['英语：punctilio','礼仪、规矩中的微小细节']]
PUNCTILIOUS=PT+[['意大利语：puntiglio → puntiglioso','细节 → 严守细节的'],['英语：punctilious〔可能经此借入〕','对礼节、规矩、细节一丝不苟的']]
PUNCHBASE=P+[['拉丁语 punct-；俗拉丁语 *punctio〔复原形式〕','刺；尖工具'],['古法语：ponchon；动词 ponchonner','尖工具；戳、打孔']]
PUNCH=PUNCHBASE+[['中古英语 punchoun / punchen','冲子；戳、击打；动词还可能受 punish 旧形式影响'],['英语：punch〔工具、击打支线〕','打孔器；打孔；拳打；一拳的力量']]
